/* Aggregate and global fixture for the kr232 adapter.
 *
 * The debugger must expand `points` (an array of structs) and read the local
 * struct passed to add(). Kept free of libc so the image links against crt0
 * alone; regenerated by tests/fixtures/kr232/regenerate.ps1. */
struct Point {
    int x;
    int y;
};

struct Point points[2];
int total;

int add(struct Point p) {
    return p.x + p.y;
}

int main(void) {
    points[0].x = 1;
    points[0].y = 2;
    points[1].x = 3;
    points[1].y = 4;
    total = add(points[0]) + points[1].x;
    return total;
}
